// src/pages/ChatApp.jsx
import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";  // for redirecting after login

const ChatApp = () => {
  const [messages, setMessages] = useState([]);
  const [chatHistory, setChatHistory] = useState([]);
  const [newMessage, setNewMessage] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const userId = "some_user_id";  // Replace this with the actual user ID from login

  // Fetch chat history from backend
  useEffect(() => {
    const fetchChatHistory = async () => {
      try {
        const response = await axios.get(`http://127.0.0.1:8000/chat_history/${userId}`);
        setChatHistory(response.data.history || []);
      } catch (error) {
        console.error("Error fetching chat history:", error);
      }
    };

    fetchChatHistory();
  }, [userId]);

  const handleSendMessage = async () => {
    if (newMessage.trim()) {
      setLoading(true);
      const userMessage = { id: Date.now(), message: newMessage, sender: "user" };

      // Add the user's message to the messages state
      setMessages((prevMessages) => [...prevMessages, userMessage]);

      // Simulate a response from the chatbot (replace with actual backend call)
      const botMessage = { id: Date.now() + 1, message: "Sure! I can help you with that.", sender: "bot" };
      setMessages((prevMessages) => [...prevMessages, botMessage]);

      setNewMessage("");  // Clear the input box
      setLoading(false);  // Stop loading

      // Send message to backend
      try {
        const response = await axios.post("http://127.0.0.1:8000/chat", {
          user_id: userId,
          user_email: "user@example.com",  // Replace with actual email from login
          message: newMessage,
          chat_id: "some_chat_id",  // Replace with actual chat ID
        });
        console.log("Chatbot response:", response.data);
      } catch (error) {
        console.error("Error sending message:", error);
      }
    }
  };

  return (
    <div className="chat-container">
      <div className="sidebar">
        <h3>Chat History</h3>
        <ul>
          {chatHistory.map((chat) => (
            <li key={chat.id}>{chat.message}</li>
          ))}
        </ul>
      </div>
      <div className="chat-area">
        <div className="chat-messages">
          {messages.map((msg) => (
            <div key={msg.id} className={msg.sender === "user" ? "user-message" : "bot-message"}>
              {msg.message}
            </div>
          ))}
        </div>
        <div className="chat-input">
          <input
            type="text"
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            placeholder="Type a message..."
            disabled={loading}
          />
          <button onClick={handleSendMessage} disabled={loading}>
            Send
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatApp;
